import Combine
import Foundation
import simd
import UntoldEngine
import UntoldComponentKit
import UntoldJoltPhysics

// Scene construction runs on the main actor; runtime state belongs to the XR
// frame thread. Controls send lock-protected requests and read status snapshots.
final class GameScene: @unchecked Sendable {
    private let physics: JoltPhysicsBackend
    private var ballEntity: EntityID = .invalid
    private var floorEntity: EntityID = .invalid
    private var sunEntity: EntityID = .invalid
    private var contactSubscription: EventSubscription?
    private let requestLock = NSLock()
    private var resetRequested = false
    private var observedFall = false
    private var observedFloorContact = false
    private var settledTime: Float = 0
    private var checkTime: Float = 0
    private var checkFinished = false

    private static let ballRadius: Float = 0.11
    private static let spawnPosition = SIMD3<Float>(0, 1.5, -3)

    /// Call before creating UntoldEngineXR: the backend choice locks on the
    /// first physics substep and persists across immersive-space reopenings.
    static func installPhysics() -> JoltPhysicsBackend? {
        var settings = JoltWorldSettings()
        settings.continuousCollision = true
        settings.maxKinematicStep = 1.0
        settings.maxKinematicSpeed = 6.0
        guard let backend = registerJoltPhysics(settings: settings) else {
            Logger.log(message: "ImmersiveGol: Jolt registration failed")
            return nil
        }
        Logger.log(message: "ImmersiveGol: active physics backend = \(backend.id)")
        return backend
    }

    @MainActor
    init(physics: JoltPhysicsBackend) {
        self.physics = physics
        setupAssetPaths()
        configureEngineSystems()
        setupPhysicsCheck()
    }

    @MainActor
    private func configureEngineSystems() {
        gameMode = true
        ScenePluginSystem.discoverInApp()
        ScenePluginSystem.install()
        ScenePluginSystem.shared.startPlayMode()
        AnimationSystem.shared.isEnabled = true
        // M1 uses a fixed world-space floor. Spatial scene manipulation would
        // move the visuals independently of their static physics bodies.
    }

    @MainActor
    private func setupPhysicsCheck() {
        let floor = CubeNode(size: 1, name: "ImmersiveGol.floor")
            .baseColor(0.12, 0.35, 0.16)
            .roughness(0.9)
            .scaleTo(x: 12, y: 0.1, z: 12)
        floorEntity = floor.entityID
        // The top of the box is y = 0, matching the XR world floor.
        translateTo(entityId: floorEntity, position: SIMD3<Float>(0, -0.05, -3))
        registerComponent(entityId: floorEntity, componentType: ColliderComponent.self)
        registerComponent(entityId: floorEntity, componentType: RigidBodyComponent.self)
        if let collider = scene.get(component: ColliderComponent.self, for: floorEntity) {
            // Collider dimensions are explicit world metres, independent of visual scale.
            collider.shape = .box(halfExtents: SIMD3<Float>(6, 0.05, 6))
            collider.friction = 0.6
            collider.restitution = 0
        }
        scene.get(component: RigidBodyComponent.self, for: floorEntity)?.motionType = .static

        let ball = SphereNode(radius: Self.ballRadius, segments: [32, 24], name: "ImmersiveGol.ball")
            .baseColor(1, 0.9, 0.3)
            .roughness(0.7)
        ballEntity = ball.entityID
        translateTo(entityId: ballEntity, position: Self.spawnPosition)
        registerComponent(entityId: ballEntity, componentType: ColliderComponent.self)
        registerComponent(entityId: ballEntity, componentType: RigidBodyComponent.self)
        if let collider = scene.get(component: ColliderComponent.self, for: ballEntity) {
            collider.shape = .sphere(radius: Self.ballRadius)
            collider.friction = 0.5
            collider.restitution = 0.35
        }
        if let body = scene.get(component: RigidBodyComponent.self, for: ballEntity) {
            body.motionType = .dynamic
            body.mass = 0.43
            body.initialLinearVelocity = .zero
        }

        let sun = DirectionalLightNode(name: "ImmersiveGol.sun")
            .color(1, 0.98, 0.92)
            .intensity(2)
            .rotateBy(angle: -50, axis: [.x])
            .rotateBy(angle: 30, axis: [.y])
        sunEntity = sun.entityID

        contactSubscription = PhysicsEvents.shared.onContact { [weak self] event in
            guard let self, event.phase == .began else { return }
            if (event.entityA == self.ballEntity && event.entityB == self.floorEntity)
                || (event.entityB == self.ballEntity && event.entityA == self.floorEntity) {
                self.observedFloorContact = true
            }
        }
        Logger.log(message: "ImmersiveGol M1: dropping ball from 1.5 m, 3 m ahead")
    }

    func requestPhysicsReset() {
        requestLock.withLock { resetRequested = true }
    }

    func update(deltaTime: Float) {
        guard gameMode else { return }
        let shouldReset = requestLock.withLock { () -> Bool in
            defer { resetRequested = false }
            return resetRequested
        }
        if shouldReset {
            if physics.resetBody(entity: ballEntity, position: Self.spawnPosition, velocity: .zero) {
                observedFall = false
                observedFloorContact = false
                settledTime = 0
                checkTime = 0
                checkFinished = false
                Logger.log(message: "ImmersiveGol M1: repeating drop check")
            } else {
                requestPhysicsReset() // Coordinator has not created the body yet.
            }
        }
        guard !checkFinished, let state = physics.bodyState(for: ballEntity) else { return }
        checkTime += deltaTime
        if state.position.y < Self.spawnPosition.y - 0.1 && state.velocity.y < -0.1 {
            observedFall = true
        }
        let resting = abs(state.position.y - Self.ballRadius) < 0.02
            && simd_length(state.velocity) < 0.05
        settledTime = resting ? settledTime + deltaTime : 0
        if observedFall && observedFloorContact && settledTime >= 0.5 {
            checkFinished = true
            Logger.log(message: "ImmersiveGol M1 PASS: ball fell, hit floor, and settled at y=\(state.position.y)")
        } else if checkTime > 10 {
            checkFinished = true
            Logger.log(message: "ImmersiveGol M1 FAIL: fall=\(observedFall), contact=\(observedFloorContact), y=\(state.position.y), speed=\(simd_length(state.velocity))")
        }
    }

    func handleInput() {}

    /// Called on the frame thread after the renderer stops.
    func shutdown() {
        contactSubscription?.cancel()
        contactSubscription = nil
        for entity in [ballEntity, floorEntity, sunEntity] where entity != .invalid {
            destroyEntity(entityId: entity)
            // Remove now so reopening does not depend on another coordinator step.
            physics.didRemoveBody(entity: entity)
        }
        ballEntity = .invalid
        floorEntity = .invalid
        sunEntity = .invalid
    }
}

@MainActor
final class EngineStatsWindowStore: ObservableObject {
    static let shared = EngineStatsWindowStore()

    @Published var advancedMode: Bool = false
    @Published private(set) var compactText: String = ""
    @Published private(set) var expandedText: String = ""

    private var timer: Timer?

    private init() {
        refresh()
        timer = Timer.scheduledTimer(withTimeInterval: 0.25, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                self.refresh()
            }
        }
    }

    deinit {
        timer?.invalidate()
    }

    private func refresh() {
        let snapshot = getEngineStatsSnapshot()
        compactText = formatEngineStatsCompact(snapshot)
        expandedText = formatEngineStatsOverlay(snapshot)
    }
}
